WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 3 ) SELECT row_to_json((SELECT "%" FROM (SELECT coalesce(json_agg( "c0"."j" ORDER BY "t0"."id" ASC NULLS LAST ), '[]') AS "nodes" , coalesce(json_agg( "c1"."j" ORDER BY "t0"."id" ASC NULLS LAST ), '[]') AS "other" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "author" ) AS "%")) AS "j" FROM (SELECT true) AS "_" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t0"."author_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" ) AS "c1" ON true ) AS "c0" ON true LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."title" AS "title" , coalesce( "c1"."j" , '[]'::json ) AS "comments" ) AS "%")) AS "j" FROM (SELECT true) AS "_" LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."comment" AS "s" WHERE ( "s"."article_id" ) IN (SELECT "id" FROM "r0" ) AND ( ( true ) ) ) SELECT "t1"."article_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) ), '[]') AS "j" FROM "r1" AS "t1" GROUP BY "t1"."article_id" ) AS "c1" ON true AND "c1"."k0" = "t0"."id" ) AS "c1" ON true
